                    x: bx + px * side * rn(3, 12) + rn(-3, 3),
                    y: by + py * side * rn(3, 12) + rn(-3, 3),
                    z: bz + rn(-5, 5),
                    vx: px * side * rn(20, 60),
                    vy: py * side * rn(20, 60),
                    vz: rn(-20, 20),
                    mode: 'billboard', sprite: theme.burst,
                    ml: 150 + rn(0, 250),
                    size0: ts * 0.03 + rn(0, ts * 0.03),
                    size1: 0,
