                    d.assign(T.max(d, core(p, n, n2, Tm, 0.03, 0.14, 1, 1, 9.2)));
                    d.assign(T.max(d, core(p, n, n2, Tm, 0.22, -0.16, 0.62, 0.78, 17.5)));
                    d.assign(T.max(d, core(p, n, n2, Tm, -0.05, -0.24, 0.55, 0.7, 27.9)));
