    /* ── Anime power-aura bursts (three-renderer EWPowerAura) ─────────────
       Power-up spells that deserve the full DBZ shroud on top of their
       particle aura. Fired from _fireAura, so it inherits the vfx3d relay
       (host emits, guest replays) — online parity for free. Only `color` is
       required; mid/core/light/ring/spark stops derive from it. `radius`
       wraps same-team units within Chebyshev range too (AoE war cries). */
    var _POWER_AURA_SPELLS = {
        raceKiCharge:      { color: 0xffd24d, durationMs: 2600 },                /* FX-4: gold, its own light (was ki blue-white) */
        warCry:            { color: 0xffb830, durationMs: 2200 },
        raceNordicWarcry:  { color: 0x7fd4ff, durationMs: 2200, radius: 2 },
        raceApeFury:       { color: 0xff7722, durationMs: 2400 },
        raceInnerDemon:    { color: 0x9933ff, durationMs: 2400 },
        overclock:         { color: 0x33ffcc, durationMs: 2000 },
        raceNitroBoost:    { color: 0x3377ff, durationMs: 2000 },
        raceHowl:          { color: 0xbfd4e8, durationMs: 2000 },
        raceAdrenalineRush:{ color: 0xffcc44, durationMs: 2000 }
    };

    function _fireAura(spellId, params) {
        if (_catOff('spells')) return;
        if (!_canSpawn()) return;
        if (!params) return;

        /* power-up shroud rides on top of the spell's particle aura (note:
           fire() only routes here for spells with an 'aura' SPELL_MAP entry —
           every _POWER_AURA_SPELLS id has one) */
        if (_POWER_AURA_SPELLS[spellId] && params.tx != null && params.ty != null &&
            window.EWPowerAura && typeof window.EWPowerAura.burst === 'function') {
            try { window.EWPowerAura.burst(params.tx, params.ty, _POWER_AURA_SPELLS[spellId]); } catch (e) {}
        }

        var auraEffectId = SPELL_MAP[spellId] && SPELL_MAP[spellId].aura;
        if (!auraEffectId) return;
        var auraDef = EFFECTS[auraEffectId];
        if (!auraDef) return;

        var tx = params.tx, ty = params.ty;
        if (tx == null || ty == null) return;

        var aoeRadius = (params.aoeRadius != null)
            ? params.aoeRadius
            : (auraDef.aoeRadius != null ? auraDef.aoeRadius : 0);
        var shape = auraDef.shape || 'square';
        var tileOffsets = _buildTileOffsets(shape, aoeRadius);
        var _mo = _maskTileOffsets(spellId, params, aoeRadius);
        if (_mo) { tileOffsets = _mo.tileOffsets; aoeRadius = _mo.aoeRadius; }

        if (auraDef.pillarSprite) {
            var c = tilePx(tx, ty);
            var zFloor = unitSurfaceZ(tx, ty);
            var pillarH = auraDef.pillarH || 180;
            _spawn({
                x: c.x, y: c.y, z: zFloor,
                mode: 'y-locked',
                sprite: auraDef.pillarSprite,
                ml: auraDef.pillarMs || 700,
                w0: auraDef.pillarW0 != null ? auraDef.pillarW0 : 60,
                w1: auraDef.pillarW1 != null ? auraDef.pillarW1 : 40,
                h0: pillarH,
                h1: auraDef.pillarH1 != null ? auraDef.pillarH1 : pillarH * 1.2,
                opacity0: auraDef.pillarOpacity0 != null ? auraDef.pillarOpacity0 : 0.9,
                opacity1: auraDef.pillarOpacity1 != null ? auraDef.pillarOpacity1 : 0,
                tint: auraDef.pillarTint != null ? auraDef.pillarTint : undefined,   /* FX-3: a blood buff's column is crimson */
            });
        }

        if (_geom3D(spellId)) {
            _geom3D(spellId)(tx, ty, aoeRadius);
        }

        _emitAoeBursts(tileOffsets, tx, ty,
            auraDef.impactTileEffect, auraDef.impactCenterEffect, aoeRadius);
    }

    function _fireTeleport(spellId, params) {
        if (_catOff('spells')) return;
        if (!_canSpawn()) return;
        if (!params) return;
        /* THE ESCAPE LOOKS (FX-5): an escape with its own look draws it instead of the shared ring + glide */
        if (_ESC_LOOKS && _ESC_LOOKS[spellId]) {
            var _efx = params.fromX != null ? params.fromX : params.sx, _efy = params.fromY != null ? params.fromY : params.sy;
            var _etx = params.toX != null ? params.toX : params.tx, _ety = params.toY != null ? params.toY : params.ty;
            if (_efx != null && _efy != null && _etx != null && _ety != null && _fx5Escape(spellId, _efx, _efy, _etx, _ety)) return;
        }
        var teleEffectId = SPELL_MAP[spellId] && SPELL_MAP[spellId].teleport;
        if (!teleEffectId) return;
        var teleDef = EFFECTS[teleEffectId];
        if (!teleDef) return;
        /* accept both spellings: fromX/toX (teleport path) and sx/tx (the
           generic travel handler) — the second used to bail out silently */
        var fromX = params.fromX != null ? params.fromX : params.sx;
        var fromY = params.fromY != null ? params.fromY : params.sy;
        var toX = params.toX != null ? params.toX : params.tx;
        var toY = params.toY != null ? params.toY : params.ty;
        if (fromX == null || fromY == null || toX == null || toY == null) return;

        var arrivalDelayMs = teleDef.arrivalDelayMs != null ? teleDef.arrivalDelayMs : 200;
        if (spellId === 'raceJellyDrift') { try { _jellyCurrent3D(fromX, fromY, toX, toY); } catch (e) {} }   // THE JELLYFISH MODELS: the current carries a few jellies along

        _spawnPortalRing3D(fromX, fromY);

        var dispersalEffectId = teleDef.dispersalEffect;
        if (dispersalEffectId) {
            var dispDef = EFFECTS[dispersalEffectId];
            if (dispDef) _spawnEffect(dispDef, { tx: fromX, ty: fromY });
        }

        var arrivalEffectId = teleDef.arrivalEffect;
        if (arrivalEffectId) {
            var arrDef = EFFECTS[arrivalEffectId];
            if (arrDef) {
                _fxDelay(function() {
                    if (_suppressed()) return;
                    _spawnEffect(arrDef, { tx: toX, ty: toY });

                    _spawnPortalRing3D(toX, toY);
                }, arrivalDelayMs);
            }
        }
    }

    function getDescentTotalMs(spellId) {
        var id = SPELL_MAP[spellId] && SPELL_MAP[spellId].descent;
        if (!id) return 0;
        var d = EFFECTS[id];
        if (!d) return 0;
        return (d.telegraphMs || 800) + (d.descentMs || 700);
    }
    function getDescentTelegraphMs(spellId) {
        var id = SPELL_MAP[spellId] && SPELL_MAP[spellId].descent;
        if (!id) return 800;
        var d = EFFECTS[id];
        return (d && d.telegraphMs) || 800;
    }
    function getDescentDescentMs(spellId) {
        var id = SPELL_MAP[spellId] && SPELL_MAP[spellId].descent;
        if (!id) return 700;
        var d = EFFECTS[id];
        return (d && d.descentMs) || 700;
    }
    /* The descent's aircraft, if one flies the payload in (the F-22 of
       Nuke / Artillery Strike) — the camera's fly-by director keys off it
       (battle.js playDetonationCinematic, 2026-09-13). */
    function getDescentFlyover(spellId) {
        var id = SPELL_MAP[spellId] && SPELL_MAP[spellId].descent;
        if (!id) return null;
        var d = EFFECTS[id];
        return (d && d.flyover) ? d.flyover : null;
    }
    function getMeteorTotalMs()     { return getDescentTotalMs('meteor'); }
    function getMeteorTelegraphMs() { return getDescentTelegraphMs('meteor'); }
    function getMeteorDescentMs()   { return getDescentDescentMs('meteor'); }

    function startRain3D(zones) {
        if (window.ThreeVFX && window.ThreeVFX.startRain3D) {
            window.ThreeVFX.startRain3D(zones);
        }
    }
    function stopRain3D() {
        if (window.ThreeVFX && window.ThreeVFX.stopRain3D) {
            window.ThreeVFX.stopRain3D();
        }
    }
    function isRain3DActive() {
        if (window.ThreeVFX && window.ThreeVFX.isRain3DActive) {
            return window.ThreeVFX.isRain3DActive();
        }
        return false;
    }

    function __playFx(effectId, tx, ty) {
        if (!EFFECTS[effectId]) { console.warn('[ThreeVFXEffects] Unknown effect:', effectId); return; }
        _spawnEffect(EFFECTS[effectId], { tx: tx || 0, ty: ty || 0 });
    }

    var _origClear = clear;
    var _clearingAll = false;
    function clearAll() {
        /* Reentrancy guard: ThreeVFX.clear() (three-vfx.js:1654) calls back
           into ThreeVFXEffects.clear — without this the two recurse forever
           (pre-existing landmine, tripped once clear() is actually used). */
        if (_clearingAll) return;
        _clearingAll = true;
        _fxCancelDelays();
        try {
        _origClear();
        /* §4.6: hard-stop every registered effect ticker and sweep the scene
           meshes of any effect still mid-flight (match end / renderer reset).
           Before the shared ticker, an interrupted effect's own rAF chain was
           the only thing that could clean it up — killed chains leaked meshes. */
        var scene = _getVFXScene();
        for (var gi = _active3DGeom.length - 1; gi >= 0; gi--) {
            try { _cleanup3D(_active3DGeom[gi]); } catch (e) {}
        }
        _active3DGeom.length = 0;
        for (var mi = _activeThreeMeshes.length - 1; mi >= 0; mi--) {
            var me = _activeThreeMeshes[mi];
            if (me && !me.done && me.meshes) {
                me.done = true;
                for (var mj = 0; mj < me.meshes.length; mj++) {
                    var mm = me.meshes[mj];
                    try {
                        if (scene) scene.remove(mm);
                        if (mm.geometry) mm.geometry.dispose();
                        if (mm.material) mm.material.dispose();
                    } catch (e) {}
                }
            }
        }
        _activeThreeMeshes.length = 0;
        for (var bi = _activeBubbleDomes.length - 1; bi >= 0; bi--) {
            var be = _activeBubbleDomes[bi];
            if (be && !be.done) {
                be.done = true;
                try {
                    if (scene) { scene.remove(be.domeOuter); scene.remove(be.domeInner); scene.remove(be.domeWire); }
                    be.matOuter.dispose(); be.matInner.dispose(); be.matWire.dispose();
                    be.geo.dispose(); be.wfGeo.dispose();
                } catch (e) {}
            }
        }
        _activeBubbleDomes.length = 0;
        for (var si = _sigEntries.length - 1; si >= 0; si--) {
            try { if (_sigEntries[si] && _sigEntries[si].finish) _sigEntries[si].finish(); } catch (e) {}
        }
        _sigEntries.length = 0;
        _fxKillAllTickers();
        if (window.ThreeVFX && window.ThreeVFX.clear) window.ThreeVFX.clear();
        try { if (window.ThreePost && window.ThreePost.dramaClear) window.ThreePost.dramaClear(); } catch (e) {}
        try { if (window.ThreePost && window.ThreePost.spellGradeClear) window.ThreePost.spellGradeClear(); } catch (e) {}
        } finally { _clearingAll = false; }
    }

    /* ════════════════════════════════════════════════════════════════════
       SPELL STAGING — the cinematic grammar layer
       ════════════════════════════════════════════════════════════════════
       WHY THIS EXISTS
       The EFFECTS/SPELL_MAP tables answer "what does this spell look like
       when it lands". They say nothing about STAGING — the wind-up, the
       world going dark, the rush lines, the flash on the frame the hit
       registers. So every spell read as: caster twitches, particles appear,
       number pops. Big spells and small spells got the same presentation,
       ~87% of the library had SOME impact VFX and the other ~13% (dashes,
       grabs, sky-drops, traps) had literally nothing, and adding a spell
       meant hand-authoring particles or shipping it invisible.

       This layer is the missing half. It gives EVERY spell — including ones
       with no bespoke VFX at all — a three-beat presentation:

         windup  (on the CASTER, at cast)    charge orb swelling into the
                                             hands, ground glyph, motes
                                             sucked inward, world dims
         burst   (on the TARGET, at impact)  flash, rush lines, shock ring,
                                             slash, sparks, bloom kick
         finish  (on the TARGET, at the end) residual glow, drifting embers,
                                             the world coming back up

       HOW A SPELL PICKS ITS LOOK (first match wins)
         1. SPELL_STAGE_MAP[id]     explicit override — the one-line hook
         2. _STAGE_BY_KIND[kind]    mechanical family (dash, pull, skyDrop…)
         3. spell.element / theme   fire, ice, divine, unholy, tech…
         4. 'arcane'                the default

       …and its INTENSITY from _stageWeight(): mp cost, tier, damage and
       aoe radius roll up to light | standard | heavy | ultimate. Only
       heavy and ultimate get the world-dim and the rush lines, so a 12 MP
       poke stays snappy and an ultimate takes the room. A spell can force
       it with `vfxWeight: 'ultimate'` in its data.js entry.

       ADDING A NEW SPELL: nothing. It gets staged automatically from its
       kind + element. To make it special, one line:
           SPELL_STAGE_MAP.myNewSpell = { archetype: 'fire', weight: 'heavy' };
       or a full custom archetype in _STAGE_ARCHETYPES.

       ONLINE PARITY: these run as three new fire() intents, and fire() is
       the function online.js wraps for the host→guest relay. Staging a new
       spell therefore costs zero online work — same as impact VFX. */

    /* Per-archetype palette + flavour. `orb`/`ring`/`flash` are hexes; the
       string knobs pick which primitive shapes the beat. Keep entries
       small — the weight tier scales counts, sizes and timings. */
    var _STAGE_ARCHETYPES = {
        arcane:   { orb: 0x9a7cff, ring: 0xb69cff, flash: '#c9b8ff', mote: 'psi-pulse',      glyph: true,  slash: false, lineColor: '#c0a8ff', moteTint: 0x9a8cff },
        /* THE FIRE PASS (2026-10-25): no glass orb on a fire cast or hit; the flames in the hand and the ring of fire out across the ground are fire's own (_fpStage) */
        fire:     { orb: 0xff7a22, ring: 0xffa544, flash: '#ffcf90', mote: 'ember',          glyph: true,  slash: false, lineColor: '#ffb066', noOrb: true },
        /* THE ICE PASS (2026-10-25): ice gathers on its own frost sigil + a growing crystal (iceSigil), not the glass orb / rune ring */
        ice:      { orb: 0x8fd8ff, ring: 0xbfeaff, flash: '#dff2ff', mote: 'frost-crystal',  glyph: false, slash: false, lineColor: '#cfeeff', noOrb: true, iceSigil: true },
        /* THE WATER PASS (2026-10-25): water staged as its kind / spellType (pink anomaly, gold grapple); its own beat
           gathers a ball of water at the caster (_wvGather) and lands the water mark on the target (_wvMark) */
        water:    { orb: 0x5fc8ff, ring: 0x9adcff, flash: '#d8f2ff', mote: 'water-splash',   glyph: false, slash: false, lineColor: '#bfe8ff', noOrb: true, water: true },
        /* spell look audit FX-2 (2026-10-26): no glass orb on a lightning hit either — "the lightning cage" read as a plain
           glass bubble that swallowed the target in close shots (Noisy Cricket, Classified Weapon, EMP, Bolt from the Blue);
           the bolt + the white rings are the hit */
        lightning:{ orb: 0xaaddff, ring: 0xffffff, flash: '#e8f6ff', mote: 'spark-elec',     glyph: false, slash: false, lineColor: '#ddf2ff', bolt: true, noOrb: true },
        divine:   { orb: 0xffe9a8, ring: 0xfff4cc, flash: '#fff6d8', mote: 'holy-light',     glyph: true,  slash: false, lineColor: '#ffeec0', pillar: true },
        /* spell look audit 2026-10-26: no glass orb dome on unholy / poison hits either — it stood in for the spell's own look
           and closed over the victim (Broken Halo, Needle Work, Devour Soul, Rot, Engulf, Kiss of Decay, Plandemic, ...) */
        unholy:   { orb: 0xb066ff, ring: 0x8833cc, flash: '#d9a8ff', mote: 'void-mist',      glyph: true,  slash: false, lineColor: '#c68cff', noOrb: true },
        tech:     { orb: 0x66e8ff, ring: 0x33bbdd, flash: '#c8f6ff', mote: 'spark-blue',     glyph: false, slash: false, lineColor: '#a8ecff' },
        alien:    { orb: 0x86ff7a, ring: 0x55dd66, flash: '#c8ffbe', mote: 'acid-green',     glyph: false, slash: false, lineColor: '#b6ffa8' },
        anomaly:  { orb: 0xff77dd, ring: 0xcc44aa, flash: '#ffc0f0', mote: 'laser-pink',     glyph: true,  slash: false, lineColor: '#ffb0ee' },
        poison:   { orb: 0x9dff5e, ring: 0x66bb33, flash: '#d8ffb0', mote: 'poison-bubble',  glyph: false, slash: false, lineColor: '#c4ff90', noOrb: true },
        /* THE NATURE PASS (2026-10-25): nature staged as poison (bubbles); its own beat throws leaves */
        nature:   { orb: 0x8dff6a, ring: 0x5cc84a, flash: '#d8ffb8', mote: 'leaf',           glyph: false, slash: false, lineColor: '#c8ffa8', noOrb: true },
        heal:     { orb: 0xa8ffc4, ring: 0x66dd99, flash: '#d8ffe8', mote: 'heal-cross',     glyph: true,  slash: false, lineColor: '#b8ffd4', gentle: true, support: 'heal' },
        /* mana: MP restoration — deep arcane blue, the heal's cool sibling.
           Distinct from tech-cyan so "mana" always reads as a resource gift. */
        mana:     { orb: 0x6faeff, ring: 0x3f86f0, flash: '#cfe2ff', mote: 'spark-blue',     glyph: true,  slash: false, lineColor: '#bcd8ff', gentle: true, support: 'mana', moteTint: 0x8fc0ff },
        /* hex: stat-down debuffs — violet corruption SINKING onto the victim.
           The support grammar plays this family's rings DOWNWARD. */
        hex:      { orb: 0xb066ff, ring: 0x9944ee, flash: '#e0c4ff', mote: 'void-mist',      glyph: true,  slash: false, lineColor: '#d0a8ff', gentle: true, support: 'debuff', moteTint: 0xbb77ff },
        human:    { orb: 0xffd9a0, ring: 0xffc880, flash: '#ffe8c8', mote: 'dust-puff',      glyph: false, slash: false, lineColor: '#ffdcb0' },
        /* ── mechanical families that had NO visuals at all ── */
        kinetic:  { orb: 0xffd9a0, ring: 0xffe0b0, flash: '#fff0d8', mote: 'dust-puff',      glyph: false, slash: true,  lineColor: '#ffe4bc', groundRush: true },
        grapple:  { orb: 0xcaa070, ring: 0xb98850, flash: '#ffe0b8', mote: 'debris',         glyph: false, slash: false, lineColor: '#ffd8a8', groundRush: true, moteTint: 0xd8b080 },
        skyfall:  { orb: 0xffb060, ring: 0xff8844, flash: '#ffe0b0', mote: 'rock-debris',    glyph: false, slash: false, lineColor: '#ffcc99', heavyLand: true },
        rig:      { orb: 0x9ad8ff, ring: 0x7ab8e0, flash: '#d0eeff', mote: 'steel-spark',    glyph: false, slash: false, lineColor: '#bfe6ff', gentle: true, moteTint: 0x9ad8ff },
        mind:     { orb: 0xd08cff, ring: 0xa060e0, flash: '#e8c8ff', mote: 'psi-pulse',      glyph: true,  slash: false, lineColor: '#dcb0ff', gentle: true, moteTint: 0xff70e0 },
        /* ── 2026-07-26 ── */
        /* ki: the martial-aura family (DBZ read) — golden power-up streaks
           in the windup (aura:true), crescents + rush lines on the hit */
        ki:       { orb: 0xffe083, ring: 0xffd24d, flash: '#fff2c0', mote: 'ember',          glyph: false, slash: true,  lineColor: '#ffe9a8', groundRush: true, aura: true, moteTint: 0xffd24d },
        /* aura: buffs/shields/war-cries — warm gold blessing, distinct from
           heal-green and divine-cream so a buff never reads as a heal */
        aura:     { orb: 0xffd76a, ring: 0xffe9a8, flash: '#fff3cc', mote: 'divine-sparkle', glyph: true,  slash: false, lineColor: '#ffeec0', gentle: true, moteTint: 0xffd76a, support: 'buff' },
    };

    /* Mechanical kind → archetype. This is what finally covers the ~60
       spells that shipped with no VFX entry: every dash, pull, sky-drop,
       sky-throw, sky-slam, trap and leap now has a look derived from what
       it DOES, not from whether someone hand-authored particles for it. */
    var _STAGE_BY_KIND = {
        dash: 'kinetic', leapStrike: 'kinetic', displacement: 'kinetic',
        linePush: 'kinetic', charge: 'kinetic',
        pull: 'grapple', aoePull: 'grapple', rallyPull: 'grapple',
        swap: 'grapple',
        skyDrop: 'skyfall', skyThrow: 'skyfall', skySlam: 'skyfall',
        bomb: 'skyfall',
        placeTrap: 'rig', deployObject: 'rig', deployTurret: 'rig',
        deployPair: 'rig', terrainCreate: 'rig', warpRune: 'rig',
        remoteView: 'mind', scan: 'mind', trickRoom: 'mind',
        tuneFrequency: 'mind', pulseLattice: 'mind',
        guard: 'rig',
        heal: 'heal', healAll: 'heal', selfHeal: 'heal', seedHeal: 'heal',
        zoneHeal: 'heal', revive: 'divine', cleanse: 'divine',
        manaRestoreAll: 'mana',
        leechSeed: 'poison', seedPoison: 'poison',
        /* buffs used to fall through to the name-regex and mostly landed on
           'arcane' — now every blessing stages as the warm gold aura family.
           Encore is a blessing too (an extra turn), so it joined the family. */
        buff: 'aura', shield: 'aura', aoeShield: 'aura', warCry: 'aura',
        encore: 'aura',
        /* debuffs used to fall through to their ELEMENT and stage like a
           damage hit (Discordance staged as an anomaly blast) — every
           stat-down now plays the sinking violet hex grammar instead */
        debuff: 'hex', zoneDebuff: 'hex',
    };

